#!/usr/bin/env node
/**
 * One stylesheet covers the whole kit. This checks the contract that makes it safe:
 *  1. Every utility class any component folder uses is generated by styles.css (the scan covers the folder, and the class is one
 *     Tailwind can build), so no component renders unstyled.
 *  2. styles.css scans only package source: no test files, and no folder outside src (automatic detection is off), so a consumer's
 *     own files never add utilities.
 *  3. The kept entries (styles-site.css, styles-docs.css) generate exactly what styles.css generates.
 * It prints the CSS size (gzip). Usage: node packages/ui/scripts/check-sources.mjs   (exit 1 on a failure)
 */
import { readdirSync, readFileSync, statSync } from 'node:fs';
import { createRequire } from 'node:module';
import { dirname, extname, join, relative, resolve } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';
import { gzipSync } from 'node:zlib';

const src = resolve(dirname(fileURLToPath(import.meta.url)), '..', 'src');
const require = createRequire(import.meta.url);
const { compile } = await import(pathToFileURL(require.resolve('@tailwindcss/node')).href);
const { Scanner } = require('@tailwindcss/oxide');

const ENTRIES = { default: ['styles.css'], site: ['styles-site.css'], 'site-docs': ['styles-site.css', 'styles-docs.css'] };
const FOLDERS = ['components', 'layout', 'shell', 'hooks', 'motion', 'docs', 'app', 'lib'];

const compileEntry = name => compile(ENTRIES[name].map(f => `@import "./${f}";`).join('\n'), { base: src, onDependency: () => {} });
const walk = d => readdirSync(d).flatMap(n => (statSync(join(d, n)).isDirectory() ? walk(join(d, n)) : [join(d, n)]));
const isSource = f => /\.(tsx?|jsx?|mjs)$/.test(f) && !/\.test\.|test-setup/.test(f);
const scanFiles = files => new Scanner({}).scanFiles(files.map(file => ({ content: readFileSync(file, 'utf8'), extension: extname(file).slice(1) })));

const compilers = Object.fromEntries(await Promise.all(Object.keys(ENTRIES).map(async n => [n, await compileEntry(n)])));
const scanned = Object.fromEntries(Object.entries(compilers).map(([n, c]) => [n, new Set(new Scanner({ sources: c.sources }).scan())]));
// build() is cumulative, so a candidate is a real utility when adding it changes the CSS.
const validOf = async candidates => {
  const compiler = await compileEntry('default');
  let last = compiler.build([]);
  return candidates.filter(c => {
    const css = compiler.build([c]);
    const grew = css !== last;
    last = css;
    return grew;
  });
};

const problems = [];
for (const folder of FOLDERS) {
  const files = walk(join(src, folder)).filter(isSource);
  const missing = (await validOf(scanFiles(files))).filter(c => !scanned.default.has(c));
  if (missing.length) problems.push(`${folder}/: ${missing.length} class(es) not generated by styles.css: ${missing.slice(0, 6).join(' ')}`);
}
const controls = (await validOf(scanFiles([join(src, 'control-recipes.mjs')]))).filter(c => !scanned.default.has(c));
if (controls.length) problems.push(`styles.css misses shared control recipes: ${controls.slice(0, 6).join(' ')}`);
const files = new Scanner({ sources: compilers.default.sources }).files.map(f => relative(src, f).split('\\').join('/'));
if (files.some(p => /\.test\.|test-setup/.test(p))) problems.push('styles.css scans test files');
if (files.some(p => p.startsWith('..'))) problems.push(`styles.css scans outside the package source: ${files.find(p => p.startsWith('..'))}`);
if (compilers.default.root !== 'none') problems.push('styles.css detects sources automatically: base.css must import tailwindcss with source(none)');
for (const entry of ['site', 'site-docs']) {
  const a = [...scanned.default].sort().join(' ');
  if ([...scanned[entry]].sort().join(' ') !== a) problems.push(`${ENTRIES[entry].join(' + ')} must generate exactly what styles.css generates`);
}

const size = gzipSync(compilers.default.build([...scanned.default]), { level: 9 }).length;
console.log(`CSS gzip: styles.css ${(size / 1024).toFixed(1)} KB`);
if (problems.length) {
  console.error(problems.map(p => `check-sources: ${p}`).join('\n'));
  process.exit(1);
}
console.log('check-sources ok: styles.css generates every class the kit uses and scans only package source');
